require 'json';require 'fileutils';require 'digest'
root=File.expand_path('..',__dir__);build=File.join(root,'server/gameServer/build/src');formal=File.join(root,'server/gameServer/src');files=Dir[File.join(build,'**/*')].select{|p|File.file?(p)};matrix=files.map do |p|rel=p.delete_prefix(build+'/');target=File.join(formal,rel);status=!File.exist?(target)?'build-only':Digest::SHA256.file(p)==Digest::SHA256.file(target)?'identical':'drifted';{path:rel,status:status,target:target.delete_prefix(root+'/')}
