result={task:'STAGE07',passed:checks.values.all?,checks:checks,counts:counts,findings:matrix.reject{|x|x[:status]=='identical'}};out=File.join(root,'work/audit/stage07-build-source-drift.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");puts "STAGE07 #{result[:passed]?'passed':'blocked'}: #{counts.fetch('build-only',0)} build-only, #{counts.fetch('drifted',0)} drifted";exit(result[:passed]?0:2)
